using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- Options with the default reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — strongly-typed metadata
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probe without throwing
//    Person is resolvable, so this succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
    Console.WriteLine($"TryGetTypeInfo<Person> → resolved ({found!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person> → not available");

// Now use a source-gen context that only knows about Person.
// Querying for an *unknown* type (UnknownType) won't throw.
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<UnknownType>(out JsonTypeInfo<UnknownType>? missing))
    Console.WriteLine($"TryGetTypeInfo<UnknownType> → resolved ({missing!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<UnknownType> → not available (no exception!)");

// --- Types ---
public record Person(string Name, int Age);
public record UnknownType(string Value);

// Source-gen context that only handles Person
[JsonSerializable(typeof(Person))]
public partial class LimitedContext : JsonSerializerContext;

